def count_vowels(text):
    vowels = set("aeıioöuü")
    count = 0
    for ch in text.replace("I", "ı").replace("İ", "i").lower():
        if ch in vowels:
            count += 1
    return count

print(count_vowels("Piko Python öğreniyor"))

