def run(commands):
    state = {"hp": 10, "gold": 0}
    for command in commands:
        parts = command.split()
        if parts[0] == "kazı" and len(parts) == 2:
            state["gold"] += int(parts[1])
        elif parts[0] == "savaş" and len(parts) == 2:
            state["hp"] -= int(parts[1])
        elif parts[0] == "iksir":
            state["hp"] = min(10, state["hp"] + 5)
        if state["hp"] <= 0:
            break
    return state

print(run(["kazı 5", "savaş 3", "iksir"]))

